using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool definitions ---
var researchTools = new ResearchTools();

// --- Build the chat client with tool support ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Run the agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries).
        2. Taking notes on key findings as you go.
        3. After gathering enough information, reviewing your notes and providing a comprehensive summary.

        Always search at least 2-3 different angles of the topic before summarizing.
        Use the TakeNote tool to record important facts as you find them.
        When done researching, use GetNotes to review all your notes, then write a final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n📋 Research Summary:\n");
Console.WriteLine(response.Text);

// --- Display collected notes ---
if (researchTools.NotesList.Count > 0)
{
    Console.WriteLine("\n📝 Research Notes Collected:");
    Console.WriteLine(new string('-', 40));
    for (int i = 0; i < researchTools.NotesList.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {researchTools.NotesList[i]}");
    }
}

Console.WriteLine("\n✅ Research complete.");

// --- Tool implementations ---
public class ResearchTools
{
    private static readonly HttpClient Http = new();
    public List<string> NotesList { get; } = [];

    [Description("Search the web for information on a query. Returns search results as text.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            // Use a web search API (DuckDuckGo instant answer API as a free fallback)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await Http.GetStringAsync(url);

            var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract/summary
            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstract_)
                results.Add($"Summary: {abstract_}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        results.Add($"- {t}");
                }
            }

            if (results.Count == 0)
                return $"Search for '{query}' returned limited results. Try a more specific query.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        NotesList.Add(note);
        Console.WriteLine($"  📝 Note taken: \"{(note.Length > 60 ? note[..60] + "..." : note)}\"");
        return $"Note saved. You now have {NotesList.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during research.")]
    public string GetNotes()
    {
        if (NotesList.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  📖 Reviewing {NotesList.Count} note(s)...");
        var numbered = NotesList.Select((n, i) => $"{i + 1}. {n}");
        return $"Your research notes:\n{string.Join("\n", numbered)}";
    }
}

